<?php
namespace App\Filament\Pages;
use App\Models\BankAccount; use App\Services\BankStatementService; use BackedEnum; use Filament\Forms\Components\DatePicker; use Filament\Forms\Components\Select; use Filament\Pages\Page; use Filament\Schemas\Components\Grid; use Filament\Schemas\Components\Section; use Filament\Schemas\Schema;
class BankStatement extends Page { protected static string|BackedEnum|null $navigationIcon='heroicon-o-document-chart-bar'; protected static ?string $navigationLabel='كشف حساب بنك'; protected static ?string $title='كشف حساب بنك'; protected static string|\UnitEnum|null $navigationGroup='الحسابات العامة'; protected static ?int $navigationSort=40; protected string $view='filament.pages.bank-statement'; public array $data=[]; public ?array $report=null;
public static function shouldRegisterNavigation():bool{return auth()->user()?->hasPermission('bank_statements.view')===true;} public static function canAccess():bool{return auth()->user()?->hasPermission('bank_statements.view')===true;}
public function mount():void{$default=BankAccount::query()->where('is_default',true)->value('id')??BankAccount::query()->value('id');$this->form->fill(['bank_account_id'=>$default,'to_date'=>now()->toDateString()]);if($default)$this->runReport();}
public function form(Schema $schema):Schema{return $schema->statePath('data')->components([Section::make('التصفية')->schema([Grid::make(3)->schema([Select::make('bank_account_id')->label('الحساب البنكي')->options(fn()=>BankAccount::query()->with('bank')->where('is_active',true)->get()->mapWithKeys(fn($a)=>[$a->id=>$a->displayName()])->all())->searchable()->preload()->required(),DatePicker::make('from_date')->label('من تاريخ')->native(false),DatePicker::make('to_date')->label('إلى تاريخ')->native(false)->afterOrEqual('from_date')])])]);}
public function runReport():void{$s=$this->form->getState();$this->report=app(BankStatementService::class)->report((int)$s['bank_account_id'],$s['from_date']??null,$s['to_date']??null);} }
